function piOtpDiagnosticText(job) {
  var otp = job && job.diagnostics && job.diagnostics.otp;
  if (!otp || !otp.dom) return '';
  var dom = otp.dom;
  var events = Array.isArray(otp.events) ? otp.events : [];
  var latest = events.length ? events[events.length - 1] : null;
  var auth = 'no auth request observed';
  if (latest) {
    var status = latest.status == null ? 'pending' : String(latest.status);
    var when = latest.timestamp ? new Date(latest.timestamp).toISOString() : 'unknown time';
    auth = String(latest.method || '?') + ' ' + String(latest.path || '/') + ' → ' + status + ' at ' + when;
    if (events.length > 1) auth += ' (+' + (events.length - 1) + ' earlier)';
  }
  return 'OTP diagnostic: input visible=' + (dom.inputVisible ? 'yes' : 'no') +
    ', count=' + Number(dom.inputCount || 0) + ', form=' + (dom.formExists ? 'yes' : 'no') +
    ', submit=' + String(dom.submitMethod || 'none') + ', validation=' + (dom.validation ? 'true' : 'false') +
    '; auth=' + auth;
}

